/* oxlint-disable shadcn/no-unknown-classes -- OpenBot source selectors are provided by the explicitly imported scoped CSS, not generated by Tailwind. */
import { observeResize } from "../../../lib/observeResize";
import { useLayoutEffect, useRef, useState, type ReactNode } from "react";

/** React port of OpenBot's SlidingTabs: same measured pill and 250ms source transition. */
export function OpenbotSlidingTabs<T extends string>({
  value,
  onChange,
  items,
  label,
}: {
  value: T;
  onChange: (value: T) => void;
  items: readonly { value: T; label: ReactNode }[];
  label: string;
}) {
  const list = useRef<HTMLDivElement>(null);
  const indicator = useRef<HTMLSpanElement>(null);
  // oxlint-disable-next-line t3code/no-unreasoned-state-sync -- Match the upstream pill's initial placement without animating from zero on mount.
  useLayoutEffect(() => {
    const frame = requestAnimationFrame(() =>
      indicator.current?.removeAttribute("data-initializing"),
    );
    return () => cancelAnimationFrame(frame);
  }, []);
  const [pill, setPill] = useState({ x: 0, width: 0 });
  // oxlint-disable-next-line t3code/no-unreasoned-state-sync -- Measure the selected DOM tab and track resizing, as in upstream SlidingTabs.
  useLayoutEffect(() => {
    const root = list.current;
    if (!root) return;
    const measure = () => {
      const tab = root.querySelector<HTMLElement>(`[data-tab-value="${CSS.escape(value)}"]`);
      if (tab)
        setPill((previous) =>
          previous.x === tab.offsetLeft && previous.width === tab.offsetWidth
            ? previous
            : { x: tab.offsetLeft, width: tab.offsetWidth },
        );
    };
    measure();
    return observeResize(
      [
        root,
        ...items.flatMap((item) => {
          const tab = root.querySelector<HTMLElement>(
            `[data-tab-value="${CSS.escape(item.value)}"]`,
          );
          return tab ? [tab] : [];
        }),
      ],
      measure,
    );
  }, [value, items]);
  return (
    <div
      ref={list}
      role="tablist"
      aria-label={label}
      className="ui-sliding-tabs"
      onKeyDown={(event) => {
        if (!["ArrowLeft", "ArrowRight", "Home", "End"].includes(event.key)) return;
        event.preventDefault();
        const index = items.findIndex((item) => item.value === value);
        const next =
          event.key === "Home"
            ? 0
            : event.key === "End"
              ? items.length - 1
              : (index + (event.key === "ArrowRight" ? 1 : -1) + items.length) % items.length;
        const item = items[next];
        if (item) {
          onChange(item.value);
          rootTab(list.current, next)?.focus();
        }
      }}
    >
      <span
        ref={indicator}
        data-initializing=""
        className="ui-sliding-tabs-pill"
        style={{ transform: `translateX(${pill.x}px)`, width: pill.width }}
        aria-hidden="true"
      />
      {items.map((item) => (
        <button
          key={item.value}
          type="button"
          role="tab"
          data-tab-value={item.value}
          aria-selected={item.value === value}
          tabIndex={item.value === value ? 0 : -1}
          className="ui-sliding-tabs-trigger"
          onClick={() => onChange(item.value)}
        >
          {item.label}
        </button>
      ))}
    </div>
  );
}
function rootTab(root: HTMLElement | null, index: number) {
  return root?.querySelectorAll<HTMLButtonElement>('[role="tab"]')[index];
}
